from pathlib import Path
import json,hashlib,shutil,copy,re
ROOT=Path(__file__).resolve().parents[3];OUT=Path(__file__).resolve().parent;DATE='2026.10.13'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
source=OUT/f'{DATE} Werkvertrag BERGER R09.json';s=json.loads(source.read_text(encoding='utf-8'))
registry=OUT/f'{DATE} Registru modificari BERGER R09.json';record=json.loads(registry.read_text(encoding='utf-8'))
hist=OUT/f'{DATE} Istoric inainte revizia comerciala';hist.mkdir(exist_ok=False)
for p in [source,registry,OUT/f'{DATE} Email BERGER R09 sursa.json']:shutil.copy2(p,hist/p.name)
changes=[]
def setv(path,value):
    target=s
    for k in path[:-1]:target=target[k]
    old=copy.deepcopy(target[path[-1]]);assert old!=value,path
    target[path[-1]]=value;changes.append({'path':path,'before':old,'after':value,'instruction':'Ultima corectură comercială expresă a utilizatorului: condiții originale; numai 3 ani/no index/18 luni adăugate comercial.'})
setv(['sections',1,'paragraphs',4], 'Der Leistungs- und Bedingungsumfang richtet sich nach diesem Vertrag und seinen Anlagen. Das Originalangebot vom 2026.08.17 nennt eine Gültigkeit von acht Wochen; diese ursprüngliche Bindungsfrist endet am 2026.10.12 und wird durch diese Vertragsvorlage nicht automatisch neu in Gang gesetzt. Vor Unterzeichnung bestätigt der AN ausdrücklich die aktuelle Gültigkeit der Honorarpositionen und des Gesamthonorars, Ressourcen und die relative Terminplanung; eine Verlängerung der Angebotsgültigkeit bedarf seiner ausdrücklichen Bestätigung. Nach beiderseitiger Unterzeichnung gelten das vereinbarte feste Honorar und der achtzehnmonatige Bauphasenrahmen nach §§ 9 und 11. Maßgeblich ist die in Anlage 2 bestätigte tatsächliche Bauteil-/Öffnungsliste einschließlich der dazu üblich erforderlichen Koordination; diese Leistung wird nicht durch pauschale Mengen-, RFI- oder Besprechungsgrenzen beschränkt. Die statischen Betreuungsbesuche richten sich nach § 7, die PI-Beschauen nach § 5. Eine echte spätere Umfangsänderung folgt § 11.')
setv(['sections',9,'paragraphs',3], 'Gesetzlich berechtigte Einwendungen gegen einzelne Entgeltteile verhindern die vereinbarte Nutzung oder Fortführung nicht. Berechtigte fällige Entgeltansprüche bleiben bestehen. Der AN erhält keine Befugnis, bereits erstellte Unterlagen allein zur Durchsetzung eines Honorarstreits zu sperren; zwingende gesetzliche Rechte, insbesondere § 1170b ABGB, bleiben unberührt.')
setv(['sections',10,'paragraphs',0], 'Das feste Gesamthonorar für das vereinbarte Paket beträgt EUR 45.000,00 netto zuzüglich gesetzlicher Umsatzsteuer; bei zwanzig Prozent EUR 54.000,00 brutto. Anlage 4 bewahrt die ursprünglichen Honorarpositionen und Beträge. Teilrechnungen und Abschlagszahlungen werden entsprechend der Erfüllung des Leistungsbildes gelegt; eine feste prozentuale Zahlungsstaffel wird nicht vereinbart. Das Honorar umfasst Planung ab T0, achtzehn Monate Bauphasenrahmen ab tatsächlichem B0 und die zugehörigen üblichen Schlussleistungen. Normale dokumentarische PI-Arbeit, erforderliche PI-Beschauen und Fertigstellungs-/Bauwerksbuchkoordination sind im Paket enthalten. Nur zusätzliche tatsächliche statische Betreuung nach § 7 wird in ausdrücklich bestellten Viererpaketen zu den Preisen der Anlage 4 gesondert vergütet. Der Paketpreis wird nicht durch ein nicht gesondert bepreistes Bauwerksbuch oder bloßen Zeitablauf stillschweigend erhöht.')
setv(['sections',11,'title'],'Abrechnung und Zahlung')
setv(['sections',11,'paragraphs'],[
 'Teilrechnungen und Abschlagszahlungen werden entsprechend der Erfüllung des Leistungsbildes gelegt. Die Rechnung weist die tatsächlich erbrachten Leistungen, ihre Zuordnung zu den Honorarpositionen der Anlage 4, Nettobetrag, Umsatzsteuer, bisherige Zahlungen und den verbleibenden Positions- und Paketbetrag nachvollziehbar aus. Ohne wirksam vereinbarte Zusätze dürfen die ursprünglichen Positionsbeträge und das Gesamtnettohonorar nicht überschritten werden. Gesondert rechtlich begründete Abrechnungen wegen Behinderung, Unterbrechung oder Abbestellung, insbesondere nach § 1168 ABGB und § 15, bleiben unberührt.',
 'Für jede dem tatsächlichen Leistungsfortschritt entsprechende prüffähige Rechnung gilt ein Zahlungsziel von vierzehn Kalendertagen ab Zugang, ohne Abzüge. Ein vertraglicher Haftrücklass oder eine zu dessen Ersatz von der AG verlangte Bankgarantie wird nicht vereinbart. Es gibt keine zusätzliche Zahlungsfreigabe- oder Abnahmefrist, die dieses Zahlungsziel automatisch verlängert. Die AG benennt konkrete Rechnungseinwendungen unverzüglich.',
 'Gesetzlich berechtigte Einwendungen wegen nicht erbrachter oder mangelhafter Leistungen sowie gesetzliche Zurückbehaltungs- und Gegenrechte bleiben erhalten. Unbestrittene fällige und sinnvoll abtrennbare Teile sind innerhalb des vereinbarten Zahlungsziels zu zahlen. Die fachliche Prüfung beziehungsweise Abnahme nach § 13 verschiebt eine objektiv berechtigte Rechnungsfälligkeit nicht automatisch; Schweigen ist keine technische Freigabe.',
 'Verzugszinsen und Betreibungskosten richten sich nach den anwendbaren gesetzlichen Regeln, insbesondere UGB §§ 456 und 458 einschließlich des gesetzlichen Pauschalbetrags von EUR 40,00, soweit dessen Voraussetzungen vorliegen. Berechtigte gesetzliche Ansprüche werden nicht durch pauschale Gebühren ersetzt oder ausgeschlossen. Eine Rechnungseinwendung binnen vierzehn Tagen ist keine Ausschlussfrist für gesetzliche Mängelrechte.',
 'Das zwingende Recht des AN auf Werklohnsicherstellung nach § 1170b ABGB bleibt erhalten. Soweit die Norm anwendbar ist, gelten die gesetzlichen Höchstbeträge für das noch ausstehende Entgelt, die angemessene Frist und die Folgen nach Abs. 2. Als Sicherungsnehmer trägt der AN die Kosten nach Abs. 1 bis zur dort vorgesehenen jährlichen Grenze von zwei Prozent der Sicherungssumme; auch die gesetzliche Ausnahme bleibt erhalten. Diese gesetzliche Sicherstellung ist von einer zugunsten der AG vereinbarten vertraglichen Retention zu unterscheiden.'])
setv(['sections',12,'paragraphs'],s['sections'][12]['paragraphs'][:4]+['Bei schuldhaftem Verzug mit einem verbindlichen Termin legt der AN unverzüglich einen Aufholplan vor. Eine Vertragsstrafe wird nicht vereinbart. Gesetzliche Leistungs-, Rücktritts- und Schadenersatzrechte bleiben unter ihren jeweiligen Voraussetzungen erhalten.'])
setv(['sections',14,'paragraphs',5], 'Die Schlussabrechnung enthält die geleisteten Teile, wirksamen Zusätze, Zahlungen sowie bei anwendbarer gesetzlicher Abrechnung ersparte und anderweitig erzielte Beträge. Binnen zehn Werktagen nach Zugang des vollständigen Beendigungsdossiers prüft die AG die bereits erbrachten abnahmefähigen Teilleistungen und dokumentiert deren Abnahme oder konkrete wesentliche Mängel; § 13 gilt entsprechend, ohne eine objektiv berechtigte Rechnungsfälligkeit nach § 12 automatisch zu verlängern. Für diese Teile läuft die vertragliche dreijährige Gewährleistung ab dokumentierter Teilabnahme beziehungsweise bei schuldhafter AG-Verzögerung nach § 13. Gesetzliche Einwendungs-, Zurückbehaltungs- und Sicherstellungsrechte bleiben unberührt; eine vertragliche Retention zugunsten der AG wird nicht begründet. Folgen einer Vertragsverletzung und Rechte wegen bereits erbrachter Leistungen werden nach dem konkreten Beendigungsgrund beurteilt. Nach berechtigter Aufhebung werden weitere Erfüllung oder Nachbesserung nicht pauschal wie bei unverändert laufendem Vertrag verlangt; fortbestehende gesetzliche Ansprüche, Vertraulichkeit und zulässige Dokumentationspflichten bleiben erhalten.')
p=s['annexes'][3]['paragraphs']
setv(['annexes',3,'paragraphs'],[
 'Die ursprünglichen Honorarpositionen und ihre Beträge sind unverändert in der folgenden Tabelle festgelegt. Das Gesamthonorar beträgt EUR 45.000,00 netto zuzüglich gesetzlicher Umsatzsteuer; bei zwanzig Prozent EUR 54.000,00 brutto. Keine zusätzliche prozentuale Zahlungsstaffel oder vertragliche Retention wird vereinbart.',
 'Teilrechnungen und Abschlagszahlungen werden entsprechend der Erfüllung des Leistungsbildes gelegt. Zahlungsziel für jede prüffähige Rechnung ist vierzehn Kalendertage ab Zugang ohne Abzüge nach § 12. Der tatsächliche Leistungsstand und die Zuordnung zu den ursprünglichen Honorarpositionen sind nachzuweisen; dieselbe Leistung wird nicht doppelt verrechnet.',
 'Prüfingenieurleistungen werden anhand der tatsächlich erbrachten Prüfungen, Befunde und Dokumentation innerhalb der eigenen Pauschale abgerechnet. Die Erstellung eigener Planungsunterlagen allein wird nicht nochmals als fremde PI-Prüfung fakturiert. Erforderliche PI-Beschauen und die normale dokumentarische Schlusskoordination bleiben im PI-Paket; ein reiner PI-Ortstermin löst kein zusätzliches statisches Betreuungspaket aus.',
 'Die normale Prüfung späterer Hersteller-/Werkstattpläne und die vollständige Bauwerksbuchleistung bleiben im vereinbarten Paket. Bereits auf abgegrenzte tatsächlich erbrachte Teilleistungen verrechnete Beträge werden bei der weiteren Abrechnung derselben Position angerechnet. Die frühere Erbringung gesetzlich fälliger vollständiger Bestands-Bauwerksbuchteile begründet kein zusätzliches Honorar. Gesetzlich berechtigte Behinderungs-/Unterbrechungs-/Beendigungsabrechnungen werden gesondert nach § 15 beurteilt.',
 p[4],p[5],p[6]])
t=s['annexes'][3]['tables'];setv(['annexes',3,'tables'],[copy.deepcopy(t[0]),copy.deepcopy(t[4]),copy.deepcopy(t[5])])
setv(['annexes',5,'tables',0,'rows'],[r for r in s['annexes'][5]['tables'][0]['rows'] if r[0]!='Bankgarantie zum Ersatz des Haftrücklasses'])
setv(['annexes',5,'tables',1,'rows',6],['Rechnung / Zahlung','Teilrechnungen und Abschlagszahlungen entsprechend der Erfüllung des Leistungsbildes; vierzehn Kalendertage ab Zugang jeder prüffähigen Rechnung ohne Abzüge. Keine feste prozentuale Zahlungsstaffel oder vertragliche Retention zugunsten der AG. Gesetzliche Gegenrechte und § 1170b bleiben unberührt.'])
setv(['annexes',5,'tables',1,'rows',7,1], 'Dreijährige vertragliche Gewährleistung mit gesetzlichen Vorbehalten. Keine Vertragsstrafe; gesetzliche Rechte wegen schuldhafter Pflichtverletzung bleiben erhalten.')
setv(['annexes',5,'tables',1,'rows',8,1], 'Projektbezogene Fortführung, native Unterlagen und Nachfolgerübergabe; freie AG-Abbestellung mit gesetzlichen §-1168-Folgen und unveränderten zwingenden Rechten. Abrechnung erbrachter Teile nach tatsächlichem Stand.')
text=json.dumps(s,ensure_ascii=False)
for bad in ['0,1 Prozent','fünf Prozent','dreißig Kalendertage','10/20/25','E1-E7','E6-Rate','EUR 166,67','bis zu sechs zusätzliche']:assert bad not in text,bad
assert s['annexes'][3]['tables'][0]==json.loads((hist/source.name).read_text(encoding='utf-8'))['annexes'][3]['tables'][0]
assert s['annexes'][3]['tables'][1]==json.loads((hist/source.name).read_text(encoding='utf-8'))['annexes'][3]['tables'][4]
source.write_text(json.dumps(s,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
shutil.copy2(source,ROOT/record['public_folder']/source.name)
record['changes'].extend(changes);record['source_R09_sha256']=sha(source)
record['commercial_instruction']='BERGER condițiile comerciale originale: 14 zile fără rețineri; facturi după prestație; 8 săptămâni valabilitate originală, fără reset. Se adaugă comercial numai Gewährleistung 3 ani, fără indexare și 18 luni Bauphasenrahmen. Corecțiile separate de vizite și excluderi rămân.'
record['sections']=len(s['sections']);record['main_paragraphs']=sum(len(x['paragraphs']) for x in s['sections']);record['annexes']=len(s['annexes'])
record['PECH_pending']='Nu se lucrează la PECH înainte de închiderea BERGER și confirmarea utilizatorului.'
registry.write_text(json.dumps(record,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
mailpath=OUT/f'{DATE} Email BERGER R09 sursa.json';mail=json.loads(mailpath.read_text(encoding='utf-8'))
find='Honorarpositionen und Preise sind in Anlage 4 festgelegt.'
assert mail['body_de'].count(find)==1
mail['body_de']=mail['body_de'].replace(find,find+' Teilrechnungen erfolgen entsprechend der Erfüllung des Leistungsbildes; Zahlungsziel sind vierzehn Kalendertage ohne Abzüge. Vereinbart sind drei Jahre Gewährleistung und ein festes Honorar ohne automatische Indexierung.')
mailpath.write_text(json.dumps(mail,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'status':'PASS','commercial_edits':len(changes),'paragraphs':record['main_paragraphs'],'base_net':45000,'payment_days':14,'Haftruecklass':False,'Vertragsstrafe':False,'PI_extra':False,'PECH_untouched':True},ensure_ascii=False))
